UPDATE "City" SET "intro" = 'Oklahoma City has two organizers. Mahj & Bougie runs social play and beginner lessons at venues around the city, including a lakeside restaurant and a downtown bar. OK LET''S MAHJONG hosts lessons, a social league and two-player events at local restaurants and bars. Events tend to include food or drinks and carry a ticket price, so check the details first. If you are new, the lesson nights are the natural place to start.' WHERE "slug" = 'oklahoma-city';
